PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?director ?directorName ?birthDate WHERE {
  VALUES ?film { dbr:Bhoomiyude_Avakashikal dbr:The_Majesty_of_the_Law }

  # Prefer dbp:director, fall back to dbo:director
  OPTIONAL { ?film dbp:director ?dirDBP . }
  OPTIONAL { ?film dbo:director ?dirDBO . }
  BIND (COALESCE(?dirDBP, ?dirDBO) AS ?director)

  # Director's English label (if available)
  OPTIONAL {
    ?director rdfs:label ?directorName .
    FILTER (lang(?directorName) = "en")
  }

  # Prefer dbp:birthDate, fall back to dbo:birthDate
  OPTIONAL { ?director dbp:birthDate ?bdateDBP . }
  OPTIONAL { ?director dbo:birthDate ?bdateDBO . }
  BIND (COALESCE(?bdateDBP, ?bdateDBO) AS ?birthDate)
}
LIMIT 100
